<script setup lang="ts">
definePageMeta({layout:'dashboard',middleware:'auth'});useSeoPage('Analytics','Account-wide click trends and audience aggregates.','/dashboard/analytics')
interface Row{label:string;value:number} interface Analytics{period:string;total_clicks:number;unique_clicks:number;average_clicks_per_link:number;timeline:Array<{date:string;clicks:number;unique_clicks:number}>;referrers:Row[];countries:Row[];devices:Row[];browsers:Row[];operating_systems:Row[]}
const period=ref('30d'); const {request}=useApi(); const {data,pending,error,refresh}=await useAsyncData('account-analytics',()=>request<{data:Analytics}>('analytics',{query:{period:period.value}}),{watch:[period]}); const topReferrer=computed(()=>data.value?.data.referrers[0]?.label||'—')
</script>
<template><div class="dashboard-page"><div class="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between"><div><h1 class="page-title">Analytics</h1><p class="mt-1 text-sm text-text-secondary">Understand how people interact with all of your links.</p></div><div class="inline-flex self-start rounded-md border border-border bg-surface2 p-0.5"><button v-for="range in ['7d','30d','90d']" :key="range" class="rounded-sm px-3 py-1.5 text-xs font-medium" :class="period===range?'bg-surface shadow-xs':'text-text-muted'" @click="period=range">{{ range==='7d'?'7 days':range==='30d'?'30 days':'90 days' }}</button></div></div><LoadingState v-if="pending" class="mt-7"/><div v-else-if="error" class="surface mt-7 p-6"><p class="text-sm text-danger">Analytics could not be loaded.</p><button class="btn-secondary mt-4" @click="refresh()">Try again</button></div><template v-else-if="data"><div class="mt-7 grid grid-cols-2 gap-3 lg:grid-cols-4"><StatCard label="Total clicks" :value="data.data.total_clicks.toLocaleString()"/><StatCard label="Unique visitors" :value="data.data.unique_clicks.toLocaleString()" tone="violet"/><StatCard label="Avg. clicks/link" :value="data.data.average_clicks_per_link.toLocaleString()" tone="blue"/><StatCard label="Top referrer" :value="topReferrer" tone="green"/></div><div class="mt-5"><AnalyticsChart :points="data.data.timeline"/></div><div class="mt-5 grid gap-5 md:grid-cols-2 lg:grid-cols-3"><section v-for="section in [{title:'Top referrers',rows:data.data.referrers},{title:'Devices',rows:data.data.devices},{title:'Browsers',rows:data.data.browsers},{title:'Operating systems',rows:data.data.operating_systems},{title:'Countries',rows:data.data.countries}]" :key="section.title" class="surface p-5"><h2 class="text-sm font-semibold">{{ section.title }}</h2><div v-if="section.rows.length" class="mt-4 grid gap-3"><div v-for="row in section.rows.slice(0,6)" :key="row.label" class="flex items-center gap-3"><span class="w-24 truncate text-xs text-text-secondary">{{ row.label }}</span><span class="h-1.5 flex-1 overflow-hidden rounded-full bg-surface2"><span class="block h-full rounded-full bg-brand" :style="{width:`${Math.max(4,(row.value/Math.max(...section.rows.map(r=>r.value)))*100)}%`}"/></span><strong class="w-10 text-right text-xs">{{ row.value }}</strong></div></div><p v-else class="mt-4 text-sm text-text-muted">No data yet.</p></section></div></template></div></template>
